+    private RuleViolationFileNameStrategy createStrategy(Properties properties) {
+        String configured = properties.getProperty(FILE_NAMES_PROPERTY_NAME);
+        if (hasConstructorStrategy) {
+            if (configured != null) {
+                throw new StoreInitializationFailedException(String.format(
+                        "Property %s cannot be configured when a rule violation file name strategy was supplied to the constructor",
+                        FILE_NAMES_PROPERTY_NAME));
+            }
+            return constructorStrategy;
+        }
+
+        configured = configured == null ? FILE_NAMES_DEFAULT : configured;
+        if ("random".equals(configured)) {
+            return __ -> UUID.randomUUID().toString();
+        }
+        if ("description".equals(configured)) {
+            return TextFileBasedViolationStore::descriptionFileName;
+        }
+
+        try {
+            Class<?> strategyClass = Class.forName(configured);
+            Object strategy = strategyClass.getConstructor().newInstance();
+            if (!(strategy instanceof RuleViolationFileNameStrategy)) {
+                throw new StoreInitializationFailedException(String.format(
+                        "%s does not implement %s", configured, RuleViolationFileNameStrategy.class.getName()));
+            }
+            return (RuleViolationFileNameStrategy) strategy;
+        } catch (StoreInitializationFailedException e) {
+            throw e;
+        } catch (ClassNotFoundException | NoSuchMethodException | InstantiationException |
+                 IllegalAccessException | InvocationTargetException e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Cannot instantiate rule violation file name strategy %s; it must have a public no-argument constructor",
+                    configured), e);
+        }
+    }
