+    private static void writeProperties(Path indexPath, Properties properties) {
+        try {
+            if (!exists(indexPath)) {
+                Files.createFile(indexPath);
+            }
+            if (!isRegularFile(indexPath)) {
+                throw new IOException("The stored rules index is not a regular file");
+            }
+            ByteArrayOutputStream bytes = new ByteArrayOutputStream();
+            properties.store(bytes, "");
+            try (FileOutputStream outputStream = new FileOutputStream(indexPath.toFile(), false)) {
+                outputStream.write(bytes.toByteArray());
+            }
+        } catch (IOException e) {
+            throw new StoreUpdateFailedException(e);
+        }
+    }
