+    private IntegritySnapshot inspect(Properties properties, Path folderPath, Path indexPath) {
+        List<IndexEntry> entries = new ArrayList<>();
+        for (String description : properties.stringPropertyNames()) {
+            String fileName = properties.getProperty(description);
