+                    ? derivedCounts.get(entry.derivedName) + 1 : 1);
+        }
+        for (IndexEntry entry : entries) {
+            entry.colliding = derivedCounts.get(entry.derivedName) > 1;
+            entry.occupied = entry.misplaced && isOccupied(entry, entries);
+        }
