+            for (Path child : children) {
+                if (!Files.isRegularFile(child) || sameFile(child, indexPath)) {
+                    continue;
+                }
+                boolean owned = false;
+                for (IndexEntry entry : entries) {
+                    if (!entry.broken && sameFile(child, entry.path)) {
+                        owned = true;
+                        break;
+                    }
+                }
+                if (!owned) {
