+    private boolean isOccupied(IndexEntry entry, List<IndexEntry> entries) {
+        Path derived = resolve(entry.derivedName);
+        if (derived == null || !isDirectChild(derived)) {
+            return true;
+        }
+        if (exists(derived)) {
+            return true;
+        }
+        for (IndexEntry other : entries) {
+            if (other != entry && other.fileName.equals(entry.derivedName)) {
+                return true;
+            }
+        }
+        return false;
+    }
