+    private boolean repair(IntegritySnapshot snapshot, Properties properties, Path indexPath) {
+        boolean changed = false;
+        for (IndexEntry entry : snapshot.entries) {
+            if (entry.shared) {
+                continue;
+            }
+            if (entry.broken) {
+                properties.remove(entry.description);
+                changed = true;
+            } else if (entry.resolved) {
+                deleteEntryFile(entry, indexPath);
+                properties.remove(entry.description);
+                changed = true;
+            } else if (entry.misplaced && !entry.colliding && !entry.occupied) {
+                moveEntry(entry, indexPath);
+                properties.setProperty(entry.description, entry.derivedName);
+                changed = true;
+            }
+        }
+        return changed;
+    }
+
+    private void moveEntry(IndexEntry entry, Path indexPath) {
+        if (sameFile(entry.path, indexPath)) {
