+            // toRealPath intentionally follows symbolic links. The index then
+            // records the new location of the file, rather than moving the link.
+            Files.move(entry.path.toRealPath(), destination);
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
