+    private static final class StoreState {
+        private final Object lock = new Object();
+        private Properties properties = new Properties();
+        private Path indexPath;
+
+        private void replace(Properties properties, Path indexPath) {
+            this.properties = properties;
+            this.indexPath = indexPath;
+        }
+
+        private IndexEntry find(String description) {
+            String normalized = ensureUnixLineBreaks(description);
+            String exact = properties.getProperty(normalized);
+            if (exact != null) {
+                return new IndexEntry(normalized, exact, null, null);
+            }
+            for (String key : properties.stringPropertyNames()) {
+                if (ensureUnixLineBreaks(key).equals(normalized)) {
+                    return new IndexEntry(key, properties.getProperty(key), null, null);
+                }
+            }
+            return null;
+        }
+
+        private List<IndexEntry> entries() {
+            List<IndexEntry> result = new ArrayList<>();
+            for (String key : properties.stringPropertyNames()) {
+                result.add(new IndexEntry(key, properties.getProperty(key), null, null));
+            }
+            return result;
+        }
+
+        private boolean records(String fileName) {
+            for (String key : properties.stringPropertyNames()) {
+                if (fileName.equals(properties.getProperty(key))) {
+                    return true;
+                }
+            }
+            return false;
+        }
+    }
+
+    private static final class IndexEntry {
+        private final String description;
+        private final String fileName;
+        private final String derivedName;
+        private final Path path;
+        private boolean broken;
+        private boolean resolved;
+        private boolean misplaced;
+        private boolean colliding;
+        private boolean occupied;
+        private boolean shared;
+
+        private IndexEntry(String description, String fileName, String derivedName, Path path) {
+            this.description = description;
+            this.fileName = fileName;
+            this.derivedName = derivedName;
+            this.path = path;
+        }
+    }
+
+    private final class IntegritySnapshot {
+        private final List<IndexEntry> entries;
+        private final List<Path> unownedFiles;
+
+        private IntegritySnapshot(List<IndexEntry> entries, List<Path> unownedFiles) {
+            this.entries = entries;
+            this.unownedFiles = unownedFiles;
+        }
+
+        private boolean hasProblems() {
+            for (IndexEntry entry : entries) {
+                if (entry.broken || entry.resolved || entry.shared || entry.misplaced || entry.colliding || entry.occupied) {
+                    return true;
